2	
3	import (
4		"context"
5		"fmt"
6		"log/slog"
7		"path/filepath"
8	
9		"github.com/aoagents/agent-orchestrator/backend/internal/adapters"
10		agentregistry "github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/registry"
11		"github.com/aoagents/agent-orchestrator/backend/internal/adapters/workspace/gitworktree"
12		"github.com/aoagents/agent-orchestrator/backend/internal/config"
13		"github.com/aoagents/agent-orchestrator/backend/internal/domain"
14		"github.com/aoagents/agent-orchestrator/backend/internal/lifecycle"
15		"github.com/aoagents/agent-orchestrator/backend/internal/observe/reaper"
16		"github.com/aoagents/agent-orchestrator/backend/internal/ports"
17		sessionsvc "github.com/aoagents/agent-orchestrator/backend/internal/service/session"
18		sessionmanager "github.com/aoagents/agent-orchestrator/backend/internal/session_manager"
19		"github.com/aoagents/agent-orchestrator/backend/internal/storage/sqlite"
20	)
21	
22	// lifecycleStack owns the runtime reaper goroutine started with the lifecycle
23	// reducer. The reducer itself is only used for wiring observations into storage.
24	type lifecycleStack struct {
25		// LCM is the Lifecycle Manager (the canonical write path). It is exposed so
26		// startSession can share the same reducer the reaper drives, rather than
27		// standing up a second store+LCM pair that would diverge under writes.
28		LCM        *lifecycle.Manager
29		reaperDone <-chan struct{}
30	}
31	
32	// startLifecycle constructs the Lifecycle Manager over the store and starts the
33	// reaper. The goroutine stops when ctx is cancelled; Stop waits for it to drain.
34	func startLifecycle(ctx context.Context, store *sqlite.Store, runtime ports.Runtime, logger *slog.Logger) *lifecycleStack {
35		lcm := lifecycle.New(store, nil)
36		rp := reaper.New(lcm, store, runtime, reaper.Config{Logger: logger})
37		return &lifecycleStack{LCM: lcm, reaperDone: rp.Start(ctx)}
38	}
39	
40	// Stop waits for the reaper goroutine to exit. The caller must cancel the ctx
41	// passed to startLifecycle before calling Stop.
42	func (l *lifecycleStack) Stop() { <-l.reaperDone }
43	
44	// startSession builds the controller-facing session service: a session manager
45	// over the real zellij runtime, a per-session gitworktree workspace, the shared
46	// store + LCM, the per-session agent resolver (AO_AGENT default), and the
47	// agent messenger. The returned service is mounted at httpd APIDeps.Sessions.
48	func startSession(cfg config.Config, runtime ports.Runtime, store *sqlite.Store, lcm *lifecycle.Manager, messenger ports.AgentMessenger, log *slog.Logger) (*sessionsvc.Service, error) {
49		agents, err := buildAgentResolver(cfg.Agent, log)
50		if err != nil {
51			return nil, err
52		}
53		ws, err := gitworktree.New(gitworktree.Options{
54			// Per-session worktrees live under the data dir, so a single AO_DATA_DIR
55			// override moves all durable per-user state together.
56			ManagedRoot: filepath.Join(cfg.DataDir, "worktrees"),
57			// Resolve each project's source repo from the projects table, so a
58			// session spawned for a registered project materialises its worktree off
59			// that repo. Unregistered projects fail loudly.
60			RepoResolver: projectRepoResolver{store: store},
61		})
62		if err != nil {
63			return nil, fmt.Errorf("session workspace: %w", err)
64		}
65		mgr := sessionmanager.New(sessionmanager.Deps{
66			Runtime:   runtime,
67			Agents:    agents,
68			Workspace: ws,
69			Store:     store,
70			Messenger: messenger,
71			Lifecycle: lcm,
72			DataDir:   cfg.DataDir,
73		})
74		return sessionsvc.New(mgr, store), nil
75	}
76	
77	// runtimeMessageSender is the narrow part of the concrete runtime needed by
78	// ao send. zellij.Runtime already implements this via SendMessage.
79	type runtimeMessageSender interface {
80		SendMessage(ctx context.Context, handle ports.RuntimeHandle, message string) error
81	}
82	
83	// runtimeMessenger sends the user's message directly to the session's live
84	// runtime pane. The HTTP controller has already validated and sanitized the
85	// message body; this adapter only resolves the stored runtime handle.
86	type runtimeMessenger struct {
87		store   *sqlite.Store
88		runtime runtimeMessageSender
89	}
90	
91	func (m runtimeMessenger) Send(ctx context.Context, id domain.SessionID, message string) error {
92		rec, ok, err := m.store.GetSession(ctx, id)
93		if err != nil {
94			return err
95		}
96		if !ok {
97			return fmt.Errorf("session %s: %w", id, sessionmanager.ErrNotFound)
98		}
99		if rec.IsTerminated {
100			return fmt.Errorf("session %s: %w", id, sessionmanager.ErrTerminated)
101		}
102		handleID := rec.Metadata.RuntimeHandleID
103		if handleID == "" {
104			return fmt.Errorf("session %s: %w", id, sessionmanager.ErrIncompleteHandle)
105		}
106		return m.runtime.SendMessage(ctx, ports.RuntimeHandle{ID: handleID}, message)
107	}
108	
109	// newSessionMessenger assembles the per-daemon agent messenger. For now, ao
110	// send is intentionally minimal: submit the message to the live runtime pane.
111	func newSessionMessenger(store *sqlite.Store, runtime runtimeMessageSender, _ *slog.Logger) ports.AgentMessenger {
112		return runtimeMessenger{store: store, runtime: runtime}
113	}
114	
115	// buildAgentRegistry returns a registry populated with the agent adapters the
116	// daemon ships, keyed by manifest id. Registration only fails on an
117	// empty/duplicate id — a programmer error, not a runtime condition.
118	// The shipped adapter list lives in the adapters/agent/registry package
119	// (registry.Constructors). Adding a new harness is a one-line edit there.
120	func buildAgentRegistry() (*adapters.Registry, error) {
121		return agentregistry.Build()
122	}
123	
124	// agentRegistry adapts the generic adapter Registry to ports.AgentResolver: it
125	// maps a session's harness onto the registered adapter of the same id and
126	// asserts that adapter drives an agent. An empty harness falls back to the
127	// daemon's configured default (AO_AGENT), so a spawn that names no harness still
128	// gets a real agent.
129	type agentRegistry struct {
130		reg            *adapters.Registry
131		defaultHarness domain.AgentHarness
132	}
133	
134	var _ ports.AgentResolver = agentRegistry{}
135	
136	func (a agentRegistry) Agent(harness domain.AgentHarness) (ports.Agent, bool) {
137		if harness == "" {
138			harness = a.defaultHarness
139		}
140		adapter, ok := a.reg.Get(string(harness))
141		if !ok {
142			return nil, false
143		}
144		agent, ok := adapter.(ports.Agent)
145		return agent, ok
146	}
147	
148	// buildAgentResolver constructs the per-session agent resolver the Session
149	// Manager consumes (sessionmanager.Deps.Agents): a registry of the shipped
150	// adapters plus the configured default harness. It fails fast if the default
151	// does not resolve, so a typo'd AO_AGENT surfaces at startup. The session lane
152	// plugs this in when it mounts the controller-facing session service at the
153	// httpd APIDeps.Sessions slot.
154	func buildAgentResolver(defaultAgent string, log *slog.Logger) (ports.AgentResolver, error) {
155		if defaultAgent == "" {
156			defaultAgent = config.DefaultAgent
157		}
158		reg, err := buildAgentRegistry()
159		if err != nil {
160			return nil, err
161		}
162		resolver := agentRegistry{reg: reg, defaultHarness: domain.AgentHarness(defaultAgent)}
163		if _, ok := resolver.Agent(""); !ok {
164			return nil, fmt.Errorf("configured default agent %q is not a registered adapter", defaultAgent)
165		}
166		ids := make([]string, 0)
167		for _, mf := range reg.Manifests() {
168			ids = append(ids, mf.ID)
